import re,sys
s=open(sys.argv[1],encoding='utf-8').read()
def txt(x): return re.sub(r'<[^>]+>','',x).strip()
nodes=re.split(r'<g class="label name"',s)[1:]
out={}
for n in nodes:
    name=txt(re.search(r'<foreignObject.*?</foreignObject>',n,re.S).group(0))
    rows=re.findall(r'class="label attribute-(type|name|keys|comment)"[^>]*>(.*?)</g>',n,re.S)
    # group sequentially
    cur={};seq=[]
    for k,v in rows:
        if k=='type': seq.append({'type':txt(v)})
        elif seq: seq[-1][k]=txt(v)
    fks=[r.get('name') for r in seq if 'FK' in r.get('keys','')]
    out[name]=fks
    print(name,'| FK:',fks)
EOF
